import { loadFont as loadSans } from "@remotion/google-fonts/Karla";
import { loadFont as loadSerif } from "@remotion/google-fonts/PlayfairDisplay";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// Achados Club — anúncio "show page": apresenta o comparador de perfumes do site e convida para o grupo de ofertas.
// Vertical, 30 s. Identidade do site: preto, dourado, títulos em Playfair Display com a palavra de destaque em
// itálico dourado, texto em Karla. Limpo: fundo preto liso, dourado só no destaque, texto que entra e fica parado.
// Abertura com os vídeos dos frascos (do cliente), depois o comparador, o grupo e a chamada.
// Versão 2 (retorno do cliente): abertura em cortes rápidos num cartão central, mais respiro e tudo longe das bordas
// (coluna de ~840 px); os critérios aparecem um por vez, grandes, em vez da tabela inteira.
// Versão 3: a comparação mostra a tela real da ferramenta (capturas de uma comparação feita no site) e o fundo preto
// ganhou um brilho dourado leve. Nada de preço inventado nas ofertas.
// Locução (ElevenLabs, 28,4 s sem o silêncio morto) entra em 0,15 s; tempos = palavra + 0,15 s.

const { fontFamily: SERIF } = loadSerif("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
loadSerif("italic", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["500", "700"], subsets: ["latin", "latin-ext"] });

export const ACH_FPS = 30;
export const ACH_FRAMES = 30 * ACH_FPS;
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.4));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BLACK = "#0B0B0B";
const CARD = "#171717";
const LINE = "rgba(217,178,76,0.28)";
const GOLD = "#D9B24C";
const GOLD_G = "linear-gradient(100deg, #F6DF8E 0%, #D9B24C 42%, #B88A25 78%, #EFD27C 100%)";
const MUTED = "rgba(255,255,255,0.58)";
const WA = "#25D366";

const T2 = 3.9, T5 = 16.7, T6 = 22.8;

const blurIn = (t: number, at: number, out?: number, d = 0.5): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.22);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), filter: `blur(${((1 - e) * 20 + o * 14).toFixed(1)}px)`, transform: `translateY(${((1 - e) * 32 - o * 16).toFixed(1)}px)` };
};
const gold: React.CSSProperties = { backgroundImage: GOLD_G, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", fontStyle: "italic", paddingRight: "0.08em" };

// título: partes em branco e partes em itálico dourado ("*assim*"), cada linha no seu tempo
type L = [string, number];
const Title: React.FC<{ t: number; lines: L[]; size: number; top: number; out?: number; align?: "center" | "left" }> = ({ t, lines, size, top, out }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center" }}>
    {lines.map(([txt, at], i) => (
      <div key={i} style={{ fontFamily: SERIF, fontWeight: 500, fontSize: size, lineHeight: 1.14, letterSpacing: "-0.015em", color: "#FFFFFF", whiteSpace: "nowrap", paddingBottom: size * 0.06, ...blurIn(t, at, out) }}>
        {txt.split("*").map((p, j) => (j % 2 ? <span key={j} style={gold}>{p}</span> : <span key={j}>{p}</span>))}
      </div>
    ))}
  </div>
);
const Glow: React.FC<{ t: number; y?: number; a?: number }> = ({ t, y = 42, a = 1 }) => (
  <AbsoluteFill style={{ background: `radial-gradient(64% 40% at ${(50 + 7 * Math.sin(t * 0.7)).toFixed(2)}% ${(y + 3 * Math.cos(t * 0.5)).toFixed(2)}%, rgba(217,178,76,${(0.2 * a * (0.84 + 0.16 * Math.sin(t * 1.3))).toFixed(3)}) 0%, rgba(217,178,76,${(0.07 * a).toFixed(3)}) 46%, rgba(217,178,76,0) 100%)` }} />
);
const Logo: React.FC<{ w: number; t: number; style?: React.CSSProperties }> = ({ w, t, style }) => (
  <div style={{ position: "absolute", width: w, ...style }}>
    <Img src={staticFile("achados/logo.png")} style={{ width: "100%", display: "block", filter: `brightness(${(1 + 0.16 * Math.max(0, Math.sin(t * 2.4)) ** 4).toFixed(3)})` }} />
  </div>
);
const Foto: React.FC<{ id: string; pos?: string; style?: React.CSSProperties }> = ({ id, pos = "50% 50%", style }) => (
  <Img src={staticFile(`achados/${id}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, display: "block", ...style }} />
);

// ───────── 1 · gancho: os frascos passam rápido num cartão central, com a pergunta embaixo ─────────
// Tudo dentro de uma coluna central (margem lateral de 120 px ou mais), com espaço entre o cartão e o texto.
const CLIPS: { src: string; a: number; b: number; from: number }[] = [
  { src: "v5", a: 0, b: 0.5, from: 1.0 },
  { src: "v2", a: 0.5, b: 0.95, from: 0.4 },
  { src: "v4", a: 0.95, b: 1.45, from: 1.5 },
  { src: "v6", a: 1.45, b: 2.36, from: 0.2 },
  { src: "v1", a: 2.36, b: T2 + 0.4, from: 0.3 },
];
const Chip: React.FC<{ t: number; at: number; out: number; x: number; y: number; rot: number; children: string }> = ({ t, at, out, x, y, rot, children }) => {
  const e = pop(t, at, 0.45), o = lin(t, out, out + 0.2);
  return (
    <div style={{ position: "absolute", left: x, top: y + Math.sin(t * 3 + x) * 6, padding: "16px 34px 18px", borderRadius: 999, backgroundImage: GOLD_G, fontFamily: SANS, fontWeight: 700, fontSize: 44, color: "#111", boxShadow: "0 18px 40px rgba(0,0,0,0.5)", opacity: Math.min(1, e * 2.5) * (1 - o), transform: `scale(${(0.3 + 0.7 * e).toFixed(3)}) rotate(${(rot * (2 - e)).toFixed(1)}deg)` }}>{children}</div>
  );
};
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const i = Math.max(0, CLIPS.findIndex((c) => t >= c.a && t < c.b));
  const c = CLIPS[i];
  const e = k(t, c.a, 0.34);
  const first = pop(t, 0, 0.5);
  // cada corte chega de um jeito: de lado, de cima, girando, de perto (nunca de baixo, para não passar sobre o texto)
  const enter = [`scale(${0.5 + 0.5 * first}) rotate(${(1 - first) * -12}deg)`, `translateX(${(1 - e) * 240}px) rotate(${(1 - e) * 7}deg)`, `translateY(${-(1 - e) * 220}px) scale(${0.9 + 0.1 * e})`, `scale(${1.28 - 0.28 * e}) rotate(${(1 - e) * -5}deg)`, `translateX(${-(1 - e) * 240}px) rotate(${(1 - e) * -7}deg)`][i];
  const beat = interpolate(t, [1.68, 1.78, 2.1], [0, 1, 0], cl) + interpolate(t, [2.92, 3.02, 3.34], [0, 1, 0], cl);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <Glow t={t} y={36} />
      <div style={{ position: "absolute", left: 270 - 16, top: 300 - 16, width: 540 + 32, height: 740 + 32, borderRadius: 72, border: `3px solid ${GOLD}`, opacity: 0.9 * beat, transform: `scale(${(1 + 0.06 * beat).toFixed(3)})` }} />
      <div style={{ position: "absolute", left: 270, top: 300 + Math.sin(t * 2.4) * 6, width: 540, height: 740, borderRadius: 56, overflow: "hidden", border: `1.5px solid ${LINE}`, boxSizing: "border-box", background: CARD, transform: `${enter} scale(${(1 + 0.04 * beat).toFixed(3)})`, filter: i > 0 && e < 1 ? `blur(${((1 - e) * 10).toFixed(1)}px)` : undefined }}>
        <AbsoluteFill style={{ transform: `scale(${(1.1 - 0.06 * lin(t, c.a, c.b)).toFixed(4)})` }}>
          <Sequence key={c.src} from={Math.round(c.a * ACH_FPS)} layout="none">
            <OffthreadVideo src={staticFile(`achados/${c.src}.mp4`)} trimBefore={Math.round(c.from * ACH_FPS)} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </Sequence>
        </AbsoluteFill>
      </div>
      <Chip t={t} at={1.66} out={2.3} x={610} y={250} rot={8}>famoso</Chip>
      <Chip t={t} at={2.9} out={T2 + 0.2} x={170} y={930} rot={-7}>bonito</Chip>
      {/* As três frases se revezam no MESMO lugar (bloco fixo, centrado em y=1335): a anterior some inteira antes de a
          próxima entrar, sem empilhar nem pular. A frase aparece já no lugar (só firma de 94% para 100%), sem subir. */}
      {([
        [0.14, 1.08, <div key="a" style={{ fontSize: 84 }}>Você escolhe perfume</div>],
        [1.24, 2.22, <div key="b" style={{ fontSize: 150 }}>pela <span style={gold}>fama</span>…</div>],
        [2.4, 99, <React.Fragment key="c"><div style={{ fontSize: 84 }}>ou pelo</div><div style={{ fontSize: 124, opacity: k(t, 2.9, 0.22), transform: `scale(${(0.94 + 0.06 * k(t, 2.9, 0.3)).toFixed(3)})` }}><span style={gold}>frasco bonito?</span></div></React.Fragment>],
      ] as [number, number, React.ReactNode][]).map(([at, out, el], n) =>
        t >= at - 0.02 && t < out + 0.14 ? (
          <div key={n} style={{ position: "absolute", left: 0, right: 0, top: 1170, height: 330, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", fontFamily: SERIF, fontWeight: 500, color: "#FFFFFF", whiteSpace: "nowrap", lineHeight: 1.12, letterSpacing: "-0.015em", opacity: k(t, at, 0.22) * (1 - lin(t, out, out + 0.12)), transform: `scale(${(0.94 + 0.06 * k(t, at, 0.3)).toFixed(3)})` }}>{el}</div>
        ) : null,
      )}
    </AbsoluteFill>
  );
};

// ───────── 2 · o comparador, com a tela real da ferramenta ─────────
// As capturas (public/achados/tela-b/c/d.jpg, 750 px de largura) são de uma comparação feita no site em 11/10/2026:
// Bleu de Chanel EDP, Asad, Invictus Victory e 1 Million Royal. Nada aqui é inventado: notas, ocasiões e veredito são
// os que a ferramenta devolveu. As barras "crescem" por uma máscara que se abre sobre a captura.
const CARDS: [string, string, string][] = [["f16", "Bleu de Chanel", "50% 50%"], ["f07", "Asad", "50% 50%"], ["f06", "Invictus Victory", "50% 50%"], ["f12", "1 Million Royal", "24% 50%"]];
const ROWS: [string, number][] = [["Fixação", 8.97], ["Projeção", 9.79], ["Ocasião", 10.58], ["Custo-benefício", 11.5]];
const CROPS: { img: string; y0: number; h: number }[] = [{ img: "tela-b", y0: 120, h: 490 }, { img: "tela-b", y0: 645, h: 490 }, { img: "tela-c", y0: 640, h: 680 }, { img: "tela-c", y0: 115, h: 490 }];
const TELA_BG = "#0F0F0F";
const CW = 190, CH = 264, GAP = 26, X0 = 121;
const FW = 840, FH = 780, FX = 120, FY = 630, SC = FW / 750;
const Tela: React.FC<{ img: string; y0: number; h: number; wipe?: number }> = ({ img, y0, h, wipe = 1 }) => (
  <div style={{ position: "relative", width: FW, height: h * SC, overflow: "hidden" }}>
    <Img src={staticFile(`achados/${img}.jpg`)} style={{ position: "absolute", left: 0, top: -y0 * SC, width: FW }} />
    {wipe < 1 ? <div style={{ position: "absolute", top: 64 * SC, bottom: 0, left: (382 + wipe * 368) * SC, right: 0, background: TELA_BG }} /> : null}
  </div>
);
const Comparador: React.FC<{ t: number }> = ({ t }) => {
  const A_OUT = 5.5, C = 8.3, D = 12.6, PRESS = 13.45, PICK = 15.36;
  const shrink = interpolate(t, [A_OUT, A_OUT + 0.6], [0, 1], { ...cl, easing: INOUT });
  const logoIn = pop(t, 4.0, 0.6);
  const lw = 500 - 340 * shrink;
  const typed = "Bleu de Chanel".slice(0, Math.round(lin(t, 5.75, 6.5) * 14));
  const bOut = lin(t, C - 0.12, C + 0.18);
  const frameIn = pop(t, C + 0.05, 0.6);
  const pick = k(t, PICK, 0.5);
  const press = interpolate(t, [PRESS, PRESS + 0.1, PRESS + 0.34], [0, 1, 0], cl);
  const scan = t >= PRESS + 0.1 && t < PICK ? ((t - PRESS - 0.1) * 1.05) % 1 : -1;
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <Glow t={t} y={44} />
      <Logo w={lw} t={t} style={{ left: 540 - lw / 2, top: 520 - 340 * shrink, opacity: Math.min(1, logoIn * 2), transform: `scale(${(0.6 + 0.4 * logoIn).toFixed(3)}) rotate(${((1 - logoIn) * -14).toFixed(1)}deg)` }} />
      {t < A_OUT + 0.3 ? (
        <>
          <div style={{ position: "absolute", left: 0, right: 0, top: 1110, textAlign: "center", fontFamily: SANS, fontWeight: 700, fontSize: 32, letterSpacing: "0.24em", color: GOLD, ...blurIn(t, 4.15, A_OUT - 0.1) }}>COMPARADOR DE PERFUMES</div>
          <Title t={t} top={1176} size={120} out={A_OUT - 0.1} lines={[["Achados Club", 4.87]]} />
        </>
      ) : null}

      {/* B · a busca e os quatro perfumes */}
      {t >= A_OUT && t < C + 0.3 ? <Title t={t} top={370} size={82} out={C - 0.12} lines={[["Até *quatro* perfumes", 5.85], ["lado a lado.", 7.43]]} /> : null}
      {t >= A_OUT && t < C + 0.25 ? (
        <>
          <div style={{ position: "absolute", left: X0, top: 620, width: 838, height: 108, borderRadius: 54, background: CARD, border: `1.5px solid ${LINE}`, display: "flex", alignItems: "center", padding: "0 10px 0 40px", boxSizing: "border-box", opacity: k(t, 5.6, 0.3) * (1 - bOut), transform: `translateY(${((1 - pop(t, 5.6, 0.5)) * 60).toFixed(1)}px)`, filter: `blur(${(bOut * 12).toFixed(1)}px)` }}>
            <span style={{ flex: 1, fontFamily: SANS, fontWeight: 500, fontSize: 40, color: typed ? "#FFFFFF" : MUTED, whiteSpace: "nowrap" }}>
              {typed || "Ex: Sauvage…"}
              {typed && t < 6.9 ? <span style={{ color: GOLD, opacity: Math.floor(t * 4) % 2 ? 1 : 0.2 }}>|</span> : null}
            </span>
            <div style={{ height: 86, padding: "0 36px", borderRadius: 43, backgroundImage: GOLD_G, display: "flex", alignItems: "center", fontFamily: SANS, fontWeight: 700, fontSize: 30, letterSpacing: "0.12em", color: "#111", transform: `scale(${(1 - 0.08 * interpolate(t, [6.5, 6.6, 6.82], [0, 1, 0], cl)).toFixed(3)})` }}>BUSCAR</div>
          </div>
          {CARDS.map(([id, nome, pos], i) => {
            const e = pop(t, 6.57 + i * 0.2, 0.5);
            return (
              <div key={id} style={{ position: "absolute", left: X0 + i * (CW + GAP), top: 800 + Math.sin(t * 2 + i * 1.4) * 5, width: CW, opacity: Math.min(1, e * 2) * (1 - bOut), transform: `translateY(${((1 - e) * 220 - bOut * 50).toFixed(1)}px) scale(${(0.8 + 0.2 * e).toFixed(3)})`, filter: `blur(${(bOut * 12).toFixed(1)}px)` }}>
                <div style={{ width: CW, height: CH, borderRadius: 28, overflow: "hidden", border: `1.5px solid ${LINE}`, boxSizing: "border-box" }}><Foto id={id} pos={pos} /></div>
                <div style={{ marginTop: 16, textAlign: "center", fontFamily: SANS, fontWeight: 700, fontSize: 24, color: "rgba(255,255,255,0.82)", whiteSpace: "nowrap" }}>{nome}</div>
              </div>
            );
          })}
        </>
      ) : null}

      {/* C · um critério por vez: a palavra grande em cima, a tela real embaixo */}
      {t >= C && t < D + 0.3 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 372, textAlign: "center" }}>
          <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 30, letterSpacing: "0.24em", color: MUTED, ...blurIn(t, 8.5, D - 0.15, 0.35) }}>COMPARE</div>
          <div style={{ position: "relative", height: 170 }}>
            {ROWS.map(([label, at], r) => {
              const next = r < ROWS.length - 1 ? ROWS[r + 1][1] - 0.08 : D - 0.15;
              return t >= at - 0.1 && t < next + 0.3 ? (
                <div key={label} style={{ position: "absolute", left: 0, right: 0, top: 6, fontFamily: SERIF, fontWeight: 500, fontSize: label.length > 10 ? 104 : 136, lineHeight: label.length > 10 ? "170px" : "160px", whiteSpace: "nowrap", ...blurIn(t, at - 0.05, next, 0.34) }}><span style={gold}>{label}</span></div>
              ) : null;
            })}
          </div>
        </div>
      ) : null}
      {t >= D ? <Title t={t} top={372} size={80} lines={[["A IA compara e diz", 12.8], ["qual é *o melhor.*", 15.12]]} /> : null}

      {t >= C ? (
        <div style={{ position: "absolute", left: FX, top: FY + Math.sin(t * 1.6) * 5, width: FW, height: FH, borderRadius: 44, background: TELA_BG, border: `${(1.5 + 1.5 * pick).toFixed(1)}px solid ${pick > 0 ? GOLD : LINE}`, boxSizing: "border-box", overflow: "hidden", boxShadow: `0 40px 90px rgba(0,0,0,0.55), 0 0 ${(90 * pick).toFixed(0)}px rgba(217,178,76,${(0.32 * pick).toFixed(2)})`, opacity: Math.min(1, frameIn * 2), transform: `translateY(${((1 - frameIn) * 300).toFixed(1)}px) scale(${(0.94 + 0.06 * frameIn + 0.02 * pick).toFixed(3)})` }}>
          {CROPS.map((c, r) => {
            const at = r === 0 ? C + 0.25 : ROWS[r][1] - 0.08;
            const next = r < ROWS.length - 1 ? ROWS[r + 1][1] - 0.08 : D - 0.1;
            if (t < at || t > next + 0.4) return null;
            const e = r === 0 ? 1 : k(t, at, 0.4), o = lin(t, next, next + 0.3);
            return (
              <div key={r} style={{ position: "absolute", left: 0, top: (FH - c.h * SC) / 2, opacity: Math.min(1, e * 2) * (1 - o), transform: `translateY(${((1 - e) * 150 - o * 150).toFixed(1)}px)` }}>
                <Tela {...c} wipe={lin(t, ROWS[r][1], ROWS[r][1] + 0.55)} />
              </div>
            );
          })}
          {/* D · o pedido do veredito (botão como no site) e a resposta real */}
          {t >= D && t < PICK + 0.3 ? (
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 44, opacity: k(t, D + 0.1, 0.35) * (1 - lin(t, PICK - 0.05, PICK + 0.2)) }}>
              <div style={{ fontFamily: SERIF, fontWeight: 500, fontSize: 66, color: "#FFFFFF" }}>Qual é o melhor?</div>
              <div style={{ padding: "30px 54px", borderRadius: 999, backgroundImage: GOLD_G, fontFamily: SANS, fontWeight: 700, fontSize: 36, letterSpacing: "0.12em", color: "#111", transform: `scale(${((0.8 + 0.2 * pop(t, D + 0.25, 0.5)) * (1 - 0.08 * press) * (1 + 0.02 * Math.sin(t * 6))).toFixed(3)})` }}>VER VEREDITO DA IA</div>
            </div>
          ) : null}
          {scan >= 0 ? <div style={{ position: "absolute", left: 0, right: 0, top: -60 + scan * (FH + 120), height: 8, backgroundImage: "linear-gradient(90deg, rgba(246,223,142,0) 0%, rgba(246,223,142,0.95) 50%, rgba(246,223,142,0) 100%)", boxShadow: "0 0 40px rgba(246,223,142,0.8)" }} /> : null}
          {t >= PICK - 0.05 ? (
            <div style={{ position: "absolute", left: 0, top: (FH - 535 * SC) / 2, opacity: Math.min(1, pick * 1.8), transform: `scale(${(0.9 + 0.1 * pick).toFixed(3)})`, filter: `blur(${((1 - pick) * 16).toFixed(1)}px)` }}>
              <Tela img="tela-d" y0={125} h={535} />
            </div>
          ) : null}
        </div>
      ) : null}
      {t >= C ? <div style={{ position: "absolute", left: 0, right: 0, top: FY + FH + 34, textAlign: "center", fontFamily: SANS, fontWeight: 500, fontSize: 30, color: "rgba(255,255,255,0.5)", opacity: k(t, 9.0, 0.4) * (t >= D && t < PICK ? 0.0 : 1) }}>tela real do comparador · achadosclub.store</div> : null}
    </AbsoluteFill>
  );
};

// ───────── 3 · o grupo de ofertas ─────────
const OFERTAS: [string, number][] = [["f03", 18.95], ["f02", 19.6], ["f04", 20.2]];
const Grupo: React.FC<{ t: number }> = ({ t }) => {
  const MAIS_OUT = 17.6;
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <Glow t={t} y={48} />
      {t < MAIS_OUT + 0.3 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 800, textAlign: "center", fontFamily: SERIF, fontWeight: 600, fontSize: 190, lineHeight: 1.1, whiteSpace: "nowrap", transform: `scale(${(1 + 0.08 * lin(t, 16.84, MAIS_OUT)).toFixed(3)})` }}>
          <span style={{ display: "inline-block", ...gold, ...blurIn(t, 16.84, MAIS_OUT - 0.05, 0.35) }}>E tem mais!</span>
        </div>
      ) : null}
      {t >= MAIS_OUT ? (
        <>
          <Title t={t} top={260} size={100} lines={[["Grupo de *ofertas*", 17.86]]} />
          <div style={{ position: "absolute", left: 0, right: 0, top: 404, textAlign: "center", fontFamily: SANS, fontWeight: 500, fontSize: 42, color: MUTED, ...blurIn(t, 20.4) }}>direto no seu WhatsApp</div>
          <div style={{ position: "absolute", left: 130, top: 540 + Math.sin(t * 1.7) * 5, width: 820, height: 930, borderRadius: 52, background: CARD, border: `1.5px solid ${LINE}`, overflow: "hidden", opacity: Math.min(1, pop(t, 17.7, 0.6) * 2), transform: `translateY(${((1 - pop(t, 17.7, 0.6)) * 260).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 150, background: "#1F1F1F", display: "flex", alignItems: "center", gap: 24, padding: "0 34px", boxSizing: "border-box" }}>
