export const Achados: React.FC = () => {
  const t = useCurrentFrame() / ACH_FPS;
  // trocas: íris (a lente da lupa abrindo) · empurrão para cima · aproximação com desfoque
  const iris = interpolate(t, [T2 - 0.2, T2 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const up = interpolate(t, [T5 - 0.24, T5 + 0.24], [0, 1], { ...cl, easing: INOUT });
  const zoom = interpolate(t, [T6 - 0.22, T6 + 0.24], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {t < T2 + 0.32 ? <Hook t={t} /> : null}
      {t >= T2 - 0.22 && t < T5 + 0.26 ? (
        <AbsoluteFill style={{ clipPath: iris < 1 ? `circle(${(iris * 1400).toFixed(0)}px at 540px 670px)` : undefined, transform: `translateY(${(-up * 1920).toFixed(1)}px)` }}>
          <Comparador t={t} />
        </AbsoluteFill>
      ) : null}
      {t >= T5 - 0.26 && t < T6 + 0.26 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - up) * 1920).toFixed(1)}px) scale(${(1 - 0.08 * zoom).toFixed(4)})`, opacity: 1 - zoom, filter: zoom > 0 ? `blur(${(zoom * 16).toFixed(1)}px)` : undefined }}>
          <Grupo t={t} />
        </AbsoluteFill>
      ) : null}
      {t >= T6 - 0.24 ? (
        <AbsoluteFill style={{ opacity: Math.min(1, zoom * 1.6), transform: `scale(${(1.2 - 0.2 * zoom).toFixed(4)})`, filter: zoom < 1 ? `blur(${((1 - zoom) * 16).toFixed(1)}px)` : undefined }}>
          <Cta t={t} />
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

